import {PARTS} from './catalog.js';
export const engineMaxThrust=p=>(PARTS[p.type].thrust||0)*(p.thrustLimit??1);
export function engineIsp(p,pressure=0){const d=PARTS[p.type];return d.ispSeaLevel===undefined?d.isp:d.isp+(d.ispSeaLevel-d.isp)*Math.max(0,Math.min(1,pressure/101325));}
export const createFuel=parts=>new Map(parts.filter(p=>PARTS[p.type].fuel||PARTS[p.type].monoprop).map(p=>[p.id,(PARTS[p.type].fuel||PARTS[p.type].monoprop)*(p.fuelLoad??1)]));
export const fuelMass=(p,fuel)=>fuel instanceof Map?(fuel.get(p.id)||0):(PARTS[p.type].fuel||PARTS[p.type].monoprop||0)*fuel*(p.fuelLoad??1);
// A separator blocks the parent edge. Its children share the discarded side's fuel.
export function fuelNetworks(parts){const byId=new Map(parts.map(p=>[p.id,p])),groups=new Map(),network=new Map();for(const p of parts){let root=p;while(root.parent&&byId.has(root.parent)&&!PARTS[root.type].decoupler&&!(PARTS[root.type].docking&&root.fuelCrossfeed===false)&&!(PARTS[byId.get(root.parent).type].docking&&byId.get(root.parent).fuelCrossfeed===false))root=byId.get(root.parent);if(!groups.has(root.id))groups.set(root.id,{parts:[],tanks:[],engines:[]});const group=groups.get(root.id);group.parts.push(p);if(PARTS[p.type].fuel&&p.fuelEnabled!==false)group.tanks.push(p);if(PARTS[p.type].thrust&&!PARTS[p.type].water)group.engines.push(p);network.set(p.id,group);}return {groups:[...groups.values()],network};}
export function engineBurn(networks,fuel,active,throttle,density,dt,pressure=density/1.225*101325){const thrust=new Map();for(const g of networks.groups){const engines=g.engines.filter(p=>active.has(p.id)),requested=engines.map(p=>engineMaxThrust(p)*throttle*(PARTS[p.type].air?density/1.225:engineIsp(p,pressure)/PARTS[p.type].isp)),need=engines.reduce((s,p,i)=>s+requested[i]*dt/(engineIsp(p,pressure)*9.81),0),available=g.tanks.reduce((s,p)=>s+(fuel.get(p.id)||0),0),fraction=need>0?Math.min(1,available/need):0;engines.forEach((p,i)=>thrust.set(p.id,requested[i]*fraction));if(available>0&&need>0){const remaining=need>=available?0:1-need/available;for(const p of g.tanks)fuel.set(p.id,(fuel.get(p.id)||0)*remaining);}}return thrust;}
// Sequential reference burn: vacuum Isp, no gravity/drag losses, burn connected tanks dry before next stage.
export function stagePerformance(parts,fuel=createFuel(parts),thermal=null){let remaining=structuredClone(parts),propellant=new Map(fuel),active=new Set();const plan=[];for(const stage of [...new Set(parts.map(p=>p.stage))].sort((a,b)=>a-b)){const removed=new Set(remaining.filter(p=>p.parent&&PARTS[p.type].decoupler&&p.stage===stage).map(p=>p.id));let more=true;while(more){more=false;for(const p of remaining)if(removed.has(p.parent)&&!removed.has(p.id)){removed.add(p.id);more=true;}}remaining=remaining.filter(p=>!removed.has(p.id));for(const p of remaining)if(p.stage===stage&&PARTS[p.type].thrust&&!PARTS[p.type].water)active.add(p.id);const networks=fuelNetworks(remaining),burning=networks.groups.filter(g=>g.engines.some(e=>active.has(e.id)&&engineMaxThrust(e)>0)&&g.tanks.some(t=>(propellant.get(t.id)||0)>0)),engines=burning.flatMap(g=>g.engines.filter(e=>active.has(e.id)&&engineMaxThrust(e)>0)),thrust=engines.reduce((s,p)=>s+engineMaxThrust(p),0);if(!thrust)continue;const before=remaining.reduce((s,p)=>s+PARTS[p.type].mass+(propellant.get(p.id)||0)+(thermal?.get(p.id)?.ablator??PARTS[p.type].ablator??0),0),fuel=burning.reduce((s,g)=>s+g.tanks.reduce((n,p)=>n+(propellant.get(p.id)||0),0),0),isp=thrust/engines.reduce((s,p)=>s+engineMaxThrust(p)/PARTS[p.type].isp,0);plan.push({stage,thrust,mass:before,seaTwr:engines.reduce((s,p)=>s+engineMaxThrust(p)*engineIsp(p,101325)/PARTS[p.type].isp,0)/(before*9.81),twr:thrust/(before*9.81),fuel,dv:isp*9.81*Math.log(before/Math.max(1,before-fuel))});for(const g of burning)for(const p of g.tanks)propellant.set(p.id,0);}return plan;}
